#include "powder/gpu_clump.hpp"
#include "powder/gpu.hpp"
#include <iostream>
#include <filesystem>
#include <fstream>
using namespace powder;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
double diff(Vec3 a,Vec3 b){return std::max({std::abs(a.x-b.x),std::abs(a.y-b.y),std::abs(a.z-b.z)});}
ClumpWorld fixture(){ClumpWorld w;w.gravity_m_s2={};MaterialContact m;m.law=ContactLaw::Linear;m.linear={1000,.01,250,.0025,.4};w.pair_models={{{0,0},m}};w.wall_models={{0,m}};auto b=make_clump(1,0,{{{},.004}},1500);b.position_m={.02,.006999,.03};w.bodies={b};FixedBox box;box.id=1;box.centre_m={0,0,.03};box.half_m={.05,.005,.03};PrescribedMotion motion;motion.pivot_m=box.centre_m;motion.rpm=5;w.moving_meshes.emplace_back(StaticTriangleMesh(triangulated_box(box)),motion);return w;}
int main(int argc,char** argv){try{auto cpu=fixture(),gpuworld=cpu;auto backend=make_gpu_backend(cpu);ClumpReport cr,gr;double error=0,loaderror=0;const double dt=1e-7;auto start=std::chrono::steady_clock::now();for(unsigned i=0;i<1000;++i){cr=cpu.step(dt);backend->advance(gpuworld,dt);if(i%100==0||i==999){backend->synchronize(gpuworld,gr);error=std::max({error,diff(cpu.bodies[0].position_m,gpuworld.bodies[0].position_m),diff(cpu.bodies[0].velocity_m_s,gpuworld.bodies[0].velocity_m_s),diff(clump_omega(cpu.bodies[0]),clump_omega(gpuworld.bodies[0]))});loaderror=std::max(loaderror,diff(cr.moving_wall_loads.at(0).reaction_torque_nm,gr.moving_wall_loads.at(0).reaction_torque_nm));}}
 check(error<1e-8&&loaderror<1e-8,"moving wall CPU/GPU mismatch");check(std::abs(cpu.moving_wall_work_j-gpuworld.moving_wall_work_j)<1e-12&&gpuworld.moving_wall_work_j!=0,"wall work parity");
 auto copied=backend->clone();auto copyworld=gpuworld;copied->advance(copyworld,dt);backend->advance(gpuworld,dt);copied->synchronize(copyworld,gr);backend->synchronize(gpuworld,gr);check(diff(copyworld.bodies[0].velocity_m_s,gpuworld.bodies[0].velocity_m_s)<1e-14,"clone lost wall history");
 ClumpRunState state;state.World=fixture();state.Dt=dt;state.Backend=make_gpu_backend(state.World);ClumpWorkerOptions options;options.paced=false;options.batch_steps=2;ClumpWorker worker(state,options);worker.single_step();auto checkpoint=worker.checkpoint();check(checkpoint.Steps==1&&checkpoint.World.physical_time_s==dt,"worker single step");worker.single_step();worker.reset(checkpoint,options);worker.single_step();auto restored=worker.checkpoint();auto expected=fixture();expected.step(dt);expected.step(dt);check(diff(restored.World.bodies[0].velocity_m_s,expected.bodies[0].velocity_m_s)<1e-10,"checkpoint independent history");worker.run();std::this_thread::sleep_for(std::chrono::milliseconds(30));worker.pause();auto count=worker.snapshot()->steps;check(count>2&&worker.snapshot()->error.empty(),"GPU worker run");std::this_thread::sleep_for(std::chrono::milliseconds(5));check(worker.snapshot()->steps==count,"pause barrier");
 auto bad=fixture();bad.wall_models[0].linear.kn*=2;bool rejected=false;try{make_gpu_backend(bad);}catch(const std::invalid_argument&){rejected=true;}check(rejected,"heterogeneous coefficients silently changed");
 // Static plane and box corner use the same physical bridge.
 for(unsigned mode=0;mode<2;++mode){auto a=fixture();a.moving_meshes.clear();a.bodies[0].position_m=mode?Vec3{.051,.006,.03}:Vec3{0,0,.001999};if(mode){FixedBox b;b.id=1;b.centre_m={0,0,.03};b.half_m={.05,.005,.03};a.boxes={b};}else a.planes.push_back({1,{0,0,1},0});auto b=a;auto engine=make_gpu_backend(b);for(unsigned i=0;i<50;++i){a.step(dt);engine->advance(b,dt);}engine->synchronize(b,gr);check(diff(a.bodies[0].velocity_m_s,b.bodies[0].velocity_m_s)<1e-10,"static geometry mismatch");}
 {MixingConfig config;config.dt=2e-6;config.duration_s=.0002;config.sample_s=.00002;auto a=fixture();a.bodies=mixing_charge(config);a.gravity_m_s2={0,0,-9.81};a.moving_meshes.clear();FixedBox blade;blade.id=1;blade.centre_m={0,0,.04};blade.half_m={.18,.01,.03};PrescribedMotion motion;motion.pivot_m=blade.centre_m;motion.rpm=30;a.moving_meshes.emplace_back(StaticTriangleMesh(triangulated_box(blade)),motion);a.planes={{1,{0,0,1},0}};auto m=a.pair_models.at({0,0});a.pair_models={{{0,0},m},{{0,1},m},{{1,1},m}};a.wall_models={{0,m},{1,m}};auto b=a;MixingMonitor ca(config,a.bodies),cb(config,b.bodies);auto engine=make_gpu_backend(b);for(unsigned step=1;step<=100;++step){a.step(config.dt);engine->advance(b,config.dt);if(step%10==0){engine->synchronize(b,gr);ca.record(a.bodies,step);cb.record(b.bodies,step);for(std::size_t i=0;i<a.bodies.size();++i)check(diff(a.bodies[i].position_m,b.bodies[i].position_m)<1e-12,"mixing trajectory mismatch");const auto& x=ca.samples.back();const auto& y=cb.samples.back();check(x.mass==y.mass&&x.index==y.index&&x.valid==y.valid&&x.count==y.count,"physical-time mixing mismatch");}}}
 // Reject a thin wall crossed completely between two exterior endpoints.
 {GpuSpheres engine;Particle p;p.id=1;p.diameter_m=.004;p.material.density_kg_m3=1500;p.position_m={-2e-8,0,0};p.velocity_m_s={1,0,0};engine.reset({p});MaterialContact m;m.law=ContactLaw::Linear;m.linear={1,0,1,0,0};engine.enable_contacts(m);GpuWall wall;wall.kind=GpuWallKind::Box;wall.half={1e-9,.01,.01};engine.set_walls({wall});bool crossing_rejected=false;try{engine.advance_contacts(1e-7,1,{});}catch(const std::runtime_error&){crossing_rejected=true;}check(crossing_rejected&&engine.physical_time_s()==0&&engine.snapshot()[0].position_m.x==p.position_m.x,"thin-wall crossing committed");}
 double wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();if(argc==2){std::filesystem::path out(argv[1]);check(std::filesystem::create_directory(out),"new output required");std::ofstream f(out/"result.csv");f<<std::setprecision(17)<<"steps,dt_s,state_error,torque_error,wall_work_j,test_wall_s\n1000,"<<dt<<','<<error<<','<<loaderror<<','<<cpu.moving_wall_work_j<<','<<wall<<'\n';}std::cout<<"GPU walls/worker passed: state "<<error<<" torque "<<loaderror<<" work "<<cpu.moving_wall_work_j<<'\n';}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
